(function(){
'use strict';
const M=AdminModel,app=M.create(),$=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let logged=false,view='rules',tab='rules',draft=null,opening=null,filter={},page=1,popup=null,pending=null,closeDraft=null,previewToken=0;
const btn=(label,act,cls='',data='')=>`<button type="button" class="${cls}" data-act="${act}" ${data}>${label}</button>`;
const badge=(s)=>`<span class="badge ${['已取消','已超时'].includes(s)?'red':['使用中','正常开放','已恢复'].includes(s)?'green':''}">${esc(s)}</span>`;
const roomName=id=>M.ROOMS.find(r=>r.id===id)?.name||'';
const roomOpts=(val,all=false)=>(all?'<option value="">全部自习室</option>':'')+M.ROOMS.map(r=>`<option value="${r.id}" ${r.id===val?'selected':''}>${esc(r.name)}</option>`).join('');
const labelInput=(label,id,value,type='text',extra='')=>`<label class="field">${label}<input id="${id}" type="${type}" value="${esc(value)}" ${extra}><small class="err" id="e-${id}"></small></label>`;
function notice(t,danger=false){return `<div class="notice ${danger?'error':''}">${t}</div>`;}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.adminToast);window.adminToast=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function modal(title,body,confirm,action,danger=false,cancel='取消'){pending=action||null;popup={title,body,confirm,danger,cancel};drawModal();}
function drawModal(){const p=popup;$('#modal').innerHTML=p?`<div class="shade"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(p.title)}"><header><h2>${esc(p.title)}</h2>${btn('关闭','dismiss','icon')}</header><div class="sheetbody">${p.body}</div><footer>${btn(p.confirm?p.cancel:p.cancel==='取消'?'关闭':p.cancel,'dismiss','secondary')}${p.confirm?btn(p.confirm,'confirm',p.danger?'danger':'primary'):''}</footer></section></div>`:'';}
function dismiss(){popup=null;pending=null;drawModal();}
function dirty(){if(draft)return Object.keys(M.DEFAULT).some(k=>String(draft[k])!==String(app.state.rules[k]));if(opening){const applied={mode:opening.mode,start:opening.start,end:opening.end};return opening.days.some(d=>JSON.stringify(app.state.schedules[opening.room][d])!==JSON.stringify(applied));}return false;}
function go(target,nextTab){const action=()=>{view=target;tab=nextTab||(target==='rules'?'rules':target==='records'?'bookings':'');draft=null;opening=null;page=1;render();};if(dirty())modal('有未保存的修改',notice('离开将放弃表单中的修改，已经保存的数据不受影响。'),'放弃修改',action,false,'继续编辑');else action();}
function exit(){const action=()=>{logged=false;draft=null;opening=null;view='rules';tab='rules';render();};if(dirty())modal('退出前有未保存修改',notice('退出将放弃未保存修改。已保存的管理端演示数据保留。'),'放弃并退出',action,false,'继续编辑');else action();}
function render(){
 $('#app').innerHTML=logged?`<div class="status"><span>13:50 · 固定演示时钟</span><span>StudySeat 管理端</span></div><header class="top"><div><p class="eyebrow">ADMIN CONSOLE</p><h1>${view==='rules'?'预约规则配置':view==='resources'?'资源关闭管理':'使用记录与日志'}</h1></div>${btn('•••','menu','icon','aria-label="管理菜单"')}</header><div class="identity"><span><i></i> admin01 · 演示管理员</span><span>独立模拟</span></div><main id="main">${view==='rules'?rulesView():view==='resources'?resourcesView():recordsView()}</main><nav>${[['rules','▤','规则配置'],['resources','▦','资源管理'],['records','◷','记录日志']].map(([v,i,t])=>btn(`<b>${i}</b>${t}`,'nav',view===v?'active':'',`data-view="${v}"`)).join('')}</nav>`:loginView();
 if(!logged)$('#loginform').onsubmit=e=>{e.preventDefault();login();};
}
function loginView(){return `<div class="login"><div class="loginbrand"><div class="brandicon">S</div><p class="eyebrow">STUDYSEAT</p><h1>管理有序，<br>专注有座。</h1><p>自习空间管理 · 管理端 MVP</p></div><section class="logincard"><h2>管理员演示登录</h2><p class="muted">独立管理场景，学生端尚未接入</p><form id="loginform" novalidate>${labelInput('演示账号','account','admin01','text','autocomplete="off"')}${labelInput('演示密码','password','','password','autocomplete="off" placeholder="请输入公开演示密码"')}<p id="loginerr" class="err" aria-live="polite"></p><button class="primary wide" type="submit">进入管理端</button></form><p class="hint">公开演示凭据：admin01 / Admin1234</p></section><p class="loginfoot">仅模拟管理操作，不接入真实认证<br>刷新后恢复初始数据，不影响学生端</p></div>`;}
function login(){let a=$('#account').value.trim(),p=$('#password').value;$('#e-account').textContent=a?'':'请输入演示账号';$('#e-password').textContent=p?'':'请输入演示密码';if(!a||!p)return;if(a!=='admin01'||p!=='Admin1234'){$('#loginerr').textContent='演示账号或密码错误';return;}logged=true;render();}
function subTabs(a,b,la,lb){return `<div class="tabs">${btn(la,'tab',tab===a?'selected':'',`data-tab="${a}"`)}${btn(lb,'tab',tab===b?'selected':'',`data-tab="${b}"`)}</div>`;}
function rulesView(){if(tab==='opening')return subTabs('rules','opening','预约规则','开放时段')+openingView();if(!draft)draft={...app.state.rules};return subTabs('rules','opening','预约规则','开放时段')+`<div class="sectionline"><b>当前规则 <span class="blue">V${app.state.version}</span></b><small>${esc(app.state.savedAt)}</small></div>`+notice('新规则仅用于新提交的预约，已有预约继续沿用创建时规则。')+`<section class="card rules">${Object.keys(M.DEFAULT).map(k=>`<label class="rulerow"><span><strong>${M.LABELS[k]}</strong><small>${{duration:'团队拟定值 · 小时',advance:'今天至当天加 N 天',early:'相对预约开始时间 · 分钟',late:'相对预约开始时间 · 分钟',leave:'超出上限判定超时 · 分钟'}[k]}</small></span><input type="text" inputmode="numeric" aria-label="${M.LABELS[k]}" data-rule="${k}" id="rule-${k}" value="${esc(draft[k])}"><small class="err field-error" id="e-rule-${k}"></small></label>`).join('')}</section><div class="actionrow">${btn('恢复默认值','defaults','secondary')}${btn('保存修改','saveRules','primary')}</div><p class="hint">参数为团队拟定演示值。业务上限待确认，当前校验必填与正整数。</p>`;}
function openingView(){if(!opening){const v=app.state.schedules.a101[2];opening={room:'a101',days:[2],...v};}return `<label class="field">自习室<select id="open-room">${roomOpts(opening.room)}</select></label><section class="card"><h3>选择星期</h3><div class="week">${Array.from({length:7},(_,i)=>btn('一二三四五六日'[i],'day',opening.days.includes(i)?'picked':'',`data-day="${i}" aria-pressed="${opening.days.includes(i)}"`)).join('')}</div><label class="field">开放方式<select id="open-mode">${['time','all','off'].map((m,i)=>`<option value="${m}" ${opening.mode===m?'selected':''}>${['指定时段','全天开放','全天不开放'][i]}</option>`).join('')}</select></label>${opening.mode==='time'?`<div class="grid">${labelInput('开放开始','open-start',opening.start,'time')}${labelInput('开放结束','open-end',opening.end,'time')}</div>`:''}<div id="opening-error" class="err" aria-live="polite"></div></section><div class="actionrow">${btn('保存开放安排','saveOpening','primary wide')}</div><h3 class="sectiontitle">已保存的本周安排</h3><section class="card compact">${app.state.schedules[opening.room].map((v,i)=>`<div class="kv"><span>周${'一二三四五六日'[i]}</span><b>${M.scheduleText(v)}</b></div>`).join('')}</section><p class="hint">只修改既有资源的开放安排；如与有效预约冲突，将保留原安排。</p>`;}
function saveRules(){const changes=Object.keys(M.DEFAULT).filter(k=>String(draft[k])!==String(app.state.rules[k]));let invalid=false;for(const k of Object.keys(M.DEFAULT)){const bad=!/^\d+$/.test(String(draft[k]))||!Number.isSafeInteger(Number(draft[k]))||Number(draft[k])<=0;$('#e-rule-'+k).textContent=bad?'请输入正整数':'';if(bad&&!invalid){$('#rule-'+k).focus();invalid=true;}}if(invalid)return;if(!changes.length){toast('内容未变化，无需保存');return;}const next={...draft};modal('确认保存规则',`<section class="card compact">${changes.map(k=>`<div class="kv"><span>${M.LABELS[k]}</span><b>${app.state.rules[k]} → ${esc(next[k])}</b></div>`).join('')}</section>`+notice('保存后生成 V'+(app.state.version+1)+'。仅影响新提交的预约，已有预约继续沿用创建时规则。'),'确认保存',()=>{app.saveRules(next);draft=null;render();toast('已保存 · 规则 V'+app.state.version);});}
function saveOpening(){const next=JSON.parse(JSON.stringify(opening));try{const trial=M.create();Object.assign(trial.state,JSON.parse(JSON.stringify(app.state)));const changed=trial.saveSchedule(next.room,next.days,{mode:next.mode,start:next.start,end:next.end});if(!changed){toast('内容未变化，无需保存');return;}}catch(e){$('#opening-error').innerHTML=esc(e.message)+(e.conflicts?e.conflicts.map(b=>`<p>${esc(b.code)} · ${b.seat} · ${b.start.slice(11)}–${b.end.slice(11)}</p>`).join(''):'');return;}modal('确认调整开放时段',`<p><b>${roomName(next.room)}</b></p><section class="card compact">${next.days.map(d=>`<div class="kv"><span>周${'一二三四五六日'[d]}</span><b>${M.scheduleText(app.state.schedules[next.room][d])} → ${M.scheduleText(next)}</b></div>`).join('')}</section>`,'确认保存',()=>{app.saveSchedule(next.room,next.days,{mode:next.mode,start:next.start,end:next.end});opening=null;render();toast('开放安排已保存，日志已更新');});}
function resourcesView(){return `<div class="sectionline"><b>资源与关闭安排</b>${btn('＋ 新增关闭','newClose','primary')}</div>`+M.ROOMS.map(r=>{const list=app.state.closures.filter(c=>c.room===r.id&&!c.restored&&c.end>M.NOW);return `<section class="card resource"><div class="resourcehead"><div class="roomicon">${r.id==='a101'?'3F':r.id==='b203'?'2F':r.id==='activity'?'24h':'2F'}</div><div><h3>${r.name}</h3><p class="muted">${r.capacity} 座 · 本周三 ${M.scheduleText(app.state.schedules[r.id][2])}</p></div></div>${list.length?notice(list.map(c=>`${c.scope==='seat'?esc(c.seat)+' 座':'整间'} · ${M.closureStatus(c)}<br>${esc(c.start.replace('T',' '))} — ${esc(c.end.replace('T',' '))}`).join('<hr>')):`<div class="resourcefoot">${badge('正常开放')}<small>无临时关闭限制</small></div>`}</section>`;}).join('')+`<h3 class="sectiontitle">关闭记录 <span class="count">${app.state.closures.length}</span></h3>`+(app.state.closures.length?app.state.closures.map(c=>`<section class="card"><div class="sectionline"><b>关闭记录 #${c.id}</b>${badge(M.closureStatus(c))}</div><h3>${M.resourceText(c)}</h3><p class="muted">${c.start.replace('T',' ')} — ${c.end.replace('T',' ')}</p><p>${esc(c.reason)}</p>${btn('查看关闭详情','closeDetail','secondary wide',`data-id="${c.id}"`)}</section>`).join(''):`<div class="empty">暂无关闭记录<p>点击“新增关闭”创建临时限制</p></div>`);}
function newClose(){closeDraft={room:'a101',scope:'seat',seat:'A09',start:'2026-10-28T14:00',end:'2026-10-28T16:00',reason:''};drawClose();}
function drawClose(){const c=closeDraft;modal('新增资源关闭',`<label class="field">自习室<select id="close-room">${roomOpts(c.room)}</select></label><label class="field">关闭范围<select id="close-scope"><option value="seat" ${c.scope==='seat'?'selected':''}>指定一个座位</option><option value="room" ${c.scope==='room'?'selected':''}>整间自习室</option></select></label>${c.scope==='seat'?`<label class="field">座位号<select id="close-seat">${M.seats(c.room).map(s=>`<option ${s===c.seat?'selected':''}>${s}</option>`).join('')}</select></label>`:''}${labelInput('关闭开始（北京时间）','close-start',c.start,'datetime-local')}${labelInput('关闭结束（北京时间）','close-end',c.end,'datetime-local')}<label class="field">关闭原因<textarea id="close-reason" maxlength="200" placeholder="例如：设备检修，2～200 字">${esc(c.reason)}</textarea></label><p id="close-error" class="err" aria-live="polite"></p>`,'预览影响',previewClose,false,'取消');}
function previewClose(){const c=JSON.parse(JSON.stringify(closeDraft));let list;try{list=app.preview(c);}catch(e){$('#close-error').textContent=e.message;return false;}const blocked=list.some(b=>b.status==='使用中'||b.status==='暂离中');const body=`<h3>${M.resourceText(c)}</h3><p>${c.start.replace('T',' ')} — ${c.end.replace('T',' ')}</p><p>原因：${esc(c.reason)}</p><div class="metric"><strong>${list.length}</strong><span>条受影响的有效预约</span></div>`+(list.length?list.map(b=>`<section class="card compact"><div class="sectionline"><b>${b.name} · ${b.seat}</b>${badge(b.status)}</div><small>${b.code}<br>${b.start.slice(11)}–${b.end.slice(11)}</small></section>`).join(''):notice('没有受影响的预约，仍可关闭资源。'))+(blocked?notice('存在正在使用的预约，请先现场确认并结束使用，再重新预览。本原型不提供强制取消。',true):notice('确认后将取消上述待签到预约，生成关闭记录、日志和通知预览。'));const token='admin-close-'+(++previewToken);modal(blocked?'无法关闭 · 需要现场处理':'确认关闭资源',body,blocked?null:'确认关闭',blocked?null:()=>{const result=app.close(c,token);if(result){render();toast('关闭已保存 · 取消 '+result.bookingIds.length+' 条预约');closeDetail(result.id);return false;}},!blocked,'返回修改');popup.onCancel=()=>drawClose();drawModal();return false;}
function closeDetail(id){const c=app.state.closures.find(c=>c.id===id);modal('关闭记录 #'+c.id,`<div class="sectionline"><b>${M.resourceText(c)}</b>${badge(M.closureStatus(c))}</div><p>${c.start.replace('T',' ')} — ${c.end.replace('T',' ')}</p><section class="card compact"><p>原因：${esc(c.reason)}</p><p>操作人：admin01 · 演示管理员</p><p>记录时间：${c.at}</p><p>取消预约：${c.bookingIds.length} 条</p>${c.restored?`<p>重新开放：${c.restoredAt}</p>`:''}</section><div class="stack">${btn('查看受影响预约','associated','secondary wide',`data-id="${id}"`)}${btn('查看通知预览（'+c.notifications.length+'）','notifications','secondary wide',`data-id="${id}"`)}${!c.restored&&c.end>M.NOW?btn('重新开放','reopen','primary wide',`data-id="${id}"`):''}</div>`);}
function recordsView(){return subTabs('bookings','logs','预约记录','操作日志')+(tab==='logs'?logsView():bookingsView());}
function bookingsView(){let list=[];try{list=app.query(filter);}catch(e){}const pages=Math.max(1,Math.ceil(list.length/5));page=Math.min(page,pages);return `<details class="card filter" open><summary>筛选预约记录</summary><div class="grid">${labelInput('开始日期','filter-from',filter.from||'','date')}${labelInput('结束日期','filter-to',filter.to||'','date')}</div><label class="field">自习室<select id="filter-room">${roomOpts(filter.room,true)}</select></label><label class="field">预约状态<select id="filter-status"><option value="">全部状态</option>${['待签到','使用中','暂离中','已结束','已超时','已取消'].map(s=>`<option ${s===filter.status?'selected':''}>${s}</option>`).join('')}</select></label>${labelInput('演示学号或座位号','filter-key',filter.key||'','text','placeholder="例如 demo-stu-a 或 A09"')}<p id="filter-error" class="err"></p><div class="actionrow">${btn('重置筛选','resetFilter','secondary')}${btn('查询','query','primary')}</div></details>${filter.closure?notice('关联关闭记录 #'+filter.closure+' '+btn('清除关联条件','clearAssociation','textbtn')):''}<div class="sectionline"><b>查询结果</b><small>共 ${list.length} 条</small></div>`+(list.length?list.slice((page-1)*5,page*5).map(b=>`<section class="card booking"><div class="sectionline"><b>${b.name}</b>${badge(b.status)}</div><small class="code">${b.code}</small><h3>${roomName(b.room)} · ${b.seat}</h3><p class="muted">${b.start.slice(0,10)} · ${b.start.slice(11)}–${b.end.slice(11)}</p><p class="muted">${b.student}</p>${b.reason?`<p class="reason">${esc(b.reason)}</p>`:''}${btn('查看预约详情','bookingDetail','secondary wide',`data-id="${b.id}"`)}</section>`).join(''):`<div class="empty">未找到符合条件的记录<p>请调整条件，或点击“重置筛选”</p></div>`)+`<div class="pagination">${btn('上一页','prev','secondary',page===1?'disabled':'')}<span>${page} / ${pages}</span>${btn('下一页','next','secondary',page===pages?'disabled':'')}</div>`;}
function logsView(){return `<div class="sectionline"><b>管理操作记录</b><small>共 ${app.state.logs.length} 条 · 只读</small></div>`+(app.state.logs.length?app.state.logs.map(l=>`<section class="card"><div class="sectionline"><b>${l.type}</b><small>#${l.id}</small></div><h3>${esc(l.object)}</h3><p class="muted">${l.at}<br>${l.actor}</p><p class="logsummary">${esc(l.detail)}</p>${btn('查看日志详情','logDetail','secondary wide',`data-id="${l.id}"`)}</section>`).join(''):`<div class="empty">暂无管理操作日志<p>保存规则、调整开放安排或关闭资源后自动生成</p></div>`);}
function bookingDetail(id){const b=app.state.bookings.find(b=>b.id===id);modal('预约详情',`<div class="sectionline"><b>${b.name} · ${b.seat}</b>${badge(b.status)}</div><small>${b.code}</small><h3>${roomName(b.room)}</h3><p>${b.start.replace('T',' ')} — ${b.end.slice(11)}</p><p class="muted">${b.student}</p>${b.reason?notice(esc(b.reason),true):''}<h3>创建时规则 · V${b.snapshot.version}</h3><section class="card compact">${Object.keys(M.DEFAULT).map(k=>`<div class="kv"><span>${M.LABELS[k]}</span><b>${b.snapshot[k]} ${k==='duration'?'小时':k==='advance'?'天':'分钟'}</b></div>`).join('')}</section><h3>状态与考勤时间线</h3><ol class="timeline">${b.events.map(e=>`<li><small>${e.at}</small><p>${esc(e.text)}</p></li>`).join('')}</ol><p class="hint">未列出的考勤事件：暂无记录。详情为只读。</p><h3>关联管理日志</h3>${app.state.logs.filter(l=>l.bookingIds.includes(id)).map(l=>`<p>${l.at} · ${l.type}</p>`).join('')||'<p class="muted">暂无关联管理日志</p>'}`);}
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.rule){draft[t.dataset.rule]=t.value;const err=$('#e-rule-'+t.dataset.rule);if(err)err.textContent='';}if(t.id.startsWith('open-')&&opening&&['open-start','open-end'].includes(t.id))opening[t.id.slice(5)]=t.value;if(t.id.startsWith('close-')&&closeDraft)closeDraft[t.id.slice(6)]=t.value;});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='open-room'){const target=t.value;const change=()=>{opening={room:target,days:[2],...app.state.schedules[target][2]};render();};if(dirty()){t.value=opening.room;modal('有未保存的开放安排',notice('切换自习室将放弃未保存的安排。'),'放弃并切换',change,false,'继续编辑');}else change();}if(t.id==='open-mode'){opening.mode=t.value;render();}if(['close-room','close-scope','close-seat'].includes(t.id)){closeDraft[t.id.slice(6)]=t.value;if(t.id==='close-room')closeDraft.seat=M.seats(closeDraft.room)[0];drawClose();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&popup){e.preventDefault();if(popup.onCancel)popup.onCancel();else dismiss();}});
document.addEventListener('click',e=>{const t=e.target.closest('[data-act]');if(!t)return;e.preventDefault();const act=t.dataset.act,id=Number(t.dataset.id);try{
 if(act==='dismiss'){if(popup?.onCancel)popup.onCancel();else dismiss();}
 else if(act==='confirm'){const fn=pending,oldPopup=popup;if(!fn)return;pending=null;const result=fn();if(result!==false)dismiss();else if(popup===oldPopup&&!pending)pending=fn;}
 else if(act==='nav')go(t.dataset.view);
 else if(act==='tab')go(view,t.dataset.tab);
 else if(act==='menu')modal('管理菜单',notice('管理端独立模拟，不影响学生端。固定场景时间：2026-10-28 13:50。刷新后恢复初始数据。')+`<div class="stack">${btn('退出管理端','logout','secondary wide')}${btn('重置演示场景','reset','secondary wide')}</div>`);
 else if(act==='logout'){dismiss();exit();}
 else if(act==='reset')modal('重置管理端演示',notice('恢复本管理端初始规则、开放安排和演示预约，清除本次管理操作与关闭记录；学生端不受影响。'),'确认重置',()=>{app.reset();draft=null;opening=null;filter={};view='rules';tab='rules';page=1;render();toast('已恢复管理端初始演示场景');},true);
 else if(act==='defaults'){draft={...M.DEFAULT};render();toast('默认值已填入，保存确认后生效');}
 else if(act==='saveRules')saveRules();
 else if(act==='day'){const day=Number(t.dataset.day);opening.days=opening.days.includes(day)?opening.days.filter(d=>d!==day):[...opening.days,day].sort();render();}
 else if(act==='saveOpening')saveOpening();
 else if(act==='newClose')newClose();
 else if(act==='closeDetail')closeDetail(id);
 else if(act==='reopen'){const c=app.state.closures.find(c=>c.id===id);modal('确认重新开放',`<h3>${M.resourceText(c)}</h3><p>${c.start.replace('T',' ')} — ${c.end.replace('T',' ')}</p>`+notice('解除本条关闭记录的剩余限制；已取消的预约不会自动恢复，其他关闭记录继续有效。'),'确认重新开放',()=>{app.reopen(id);render();toast('已重新开放，原取消记录仍保留');});}
 else if(act==='associated'){filter={closure:id};page=1;dismiss();go('records','bookings');}
 else if(act==='notifications'){const c=app.state.closures.find(c=>c.id===id);modal('关闭通知内容预览',notice('仅管理端内容预览，未实际发送，学生端不会收到。')+(c.notifications.length?c.notifications.map(n=>`<section class="card"><p>${esc(n.text)}</p><small>预约 ${app.state.bookings.find(b=>b.id===n.bookingId).code}</small></section>`).join(''):'<p>没有受影响预约，无需生成通知预览。</p>'));}
 else if(act==='query'){const next={from:$('#filter-from').value,to:$('#filter-to').value,room:$('#filter-room').value,status:$('#filter-status').value,key:$('#filter-key').value.trim(),closure:filter.closure};try{app.query(next);}catch(err){$('#filter-error').textContent=err.message;return;}filter=next;page=1;render();}
 else if(act==='resetFilter'){filter={};page=1;render();}
 else if(act==='clearAssociation'){delete filter.closure;page=1;render();}
 else if(act==='prev'||act==='next'){page+=act==='next'?1:-1;render();}
 else if(act==='bookingDetail')bookingDetail(id);
 else if(act==='logDetail'){const l=app.state.logs.find(l=>l.id===id);modal('操作日志 #'+id,`<h3>${esc(l.type)} · ${esc(l.object)}</h3><p class="muted">${l.at}<br>${l.actor}</p><pre>${esc(l.detail)}</pre><h3>关联预约</h3>${l.bookingIds.map(id=>`<p>${app.state.bookings.find(b=>b.id===id).code}</p>`).join('')||'<p class="muted">本次操作无关联预约</p>'}`);}
 }catch(err){toast(err.message);}
});
render();
})();
